#include <stdio.h>

int main(void) {
    int r = 8, x = 0, y = r, p = 1 - r, k = 0;
    printf("k x y p\n");
    printf("%d %d %d %d\n", k, x, y, p);
    while (x < y) {
        x = x + 1;
        if (p < 0) {
            p = p + 2 * x + 1;
        } else {
            y = y - 1;
            p = p + 2 * (x - y) + 1;
        }
        k = k + 1;
        printf("%d %d %d %d\n", k, x, y, p);
    }
    return 0;
}
